    public Object parseOpenInterest(Object interest, Map<String, Object> market)
    {
        //
        //     {
        //         "high": 93099.5,
        //         "low": 81773.0,
        //         "last": 87197.0,
        //         "instrument_name": "BTC-PERPETUAL",
        //         "bid_price": 87083.0,
        //         "ask_price": 87149.5,
        //         "open_interest": 9978911260,
        //         "mark_price": 87102.01,
        //         "creation_timestamp": 1763674177068,
        //         "price_change": -3.2032,
        //         "volume": 7377.18657991,
        //         "estimated_delivery_price": 87047.2,
        //         "base_currency": "BTC",
        //         "quote_currency": "USD",
        //         "volume_usd": 661040250.0,
        //         "volume_notional": 661040250.0,
        //         "current_funding": 1.2966e-4,
        //         "funding_8h": -8.1069e-4,
        //         "mid_price": 87116.25
        //     }
        //
        Long timestamp = this.safeInteger(interest, "creation_timestamp");
        String marketId = this.safeString(interest, "instrument_name");
        Map<String, Object> marketResolved = this.safeMarket(marketId, market, (String) null, (String) null);
        Double openInterest = this.safeNumber(interest, "open_interest", (Object) null);
        Double openInterestAmount = null;
        Double openInterestValue = null;
        if ((java.util.Objects.equals(marketResolved.get("option"), true)) || ((java.util.Objects.equals(marketResolved.get("future"), true)) && (java.util.Objects.equals(marketResolved.get("linear"), true))))
        {
            openInterestAmount = openInterest;
        } else
        {
            openInterestValue = openInterest;
        }
        return this.safeOpenInterest(Helpers.newMap(
            "symbol", this.safeSymbol(marketId, marketResolved, (String) null, (String) null),
            "openInterestAmount", openInterestAmount,
            "openInterestValue", openInterestValue,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "info", interest
        ), marketResolved);
    }

